package ama.minutes.contract;

import ama.material.*;
import ama.contract.MinutesContracts.*;
import ama.canonical.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static ama.canonical.CanonicalValue.*;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;

/** Enumerates every approved parsed unit, independently of whether any previous output cited it. */
final class MaterialCatalog {
 static List<CatalogFact> facts(StoredFactsIndex index,String meeting,String snapshot,GenerationConfiguration config){
  if(snapshot==null){require(config.parserSelections().isEmpty(),SOURCE_MEMBERSHIP_MISMATCH);return List.of();}
  require(config.profiles().definition(ProfileKind.CATALOG).version().equals(MaterialProfiles.CATALOG),PROFILE_UNAVAILABLE);index.meeting(index.one(Table.MATERIAL_SNAPSHOT,snapshot,PROVENANCE_UNAVAILABLE),meeting);var out=new ArrayList<CatalogFact>();
  var selections=MaterialBinding.selections(index.facts,meeting,snapshot,config.inputId());require(selections.equals(config.parserSelections()),SOURCE_MEMBERSHIP_MISMATCH);
  for(var selection:selections){check(index.cancelled);var revision=index.one(Table.MATERIAL_REVISION,selection.materialRevisionId(),PROVENANCE_UNAVAILABLE);var reference=index.one(Table.MATERIAL_REFERENCE,revision.string("reference_id"),PROVENANCE_UNAVAILABLE);index.meeting(reference,meeting);var document=index.single(index.matching(Table.PARSED_DOCUMENT,"material_revision_id",selection.materialRevisionId()).stream().filter(d->selection.parserVersion().equals(d.string("parser_version"))).toList(),PROVENANCE_UNAVAILABLE);String format=MaterialProfiles.format(selection.parserVersion());String file=revision.nullableString("content_file_id"),textFile=document.nullableString("text_file_id");require(file!=null&&textFile!=null,PROVENANCE_UNAVAILABLE);var content=index.file(file);var parsed=index.file(textFile);require(meeting.equals(content.meetingId())&&meeting.equals(parsed.meetingId())&&content.sha256().equals(revision.string("content_hash")),SOURCE_MEMBERSHIP_MISMATCH);
   var units=new ArrayList<>(index.matching(Table.PARSED_UNIT,"document_id",document.string("id")));units.sort(Comparator.comparingLong(u->u.number("ordinal")));require(!units.isEmpty()&&units.size()==document.number("unit_count"),SOURCE_MEMBERSHIP_MISMATCH);long ordinal=0;var sourceUnits=new ArrayList<SourceUnit>();var text=new StringBuilder();var locators=new HashSet<Locator>();
   for(var unit:units){check(index.cancelled);require(unit.number("ordinal")==++ordinal&&!unit.string("body").isBlank(),SOURCE_MEMBERSHIP_MISMATCH);if(!text.isEmpty())text.append("\n\n");text.append(unit.string("body"));require(text.length()<=index.budget.canonical().maxEncodedBytes(),BUDGET_EXCEEDED);sourceUnits.add(new SourceUnit(unit.number("ordinal"),unit.nullableNumber("page_no"),unit.nullableNumber("paragraph_no"),unit.nullableString("section_path")));}
   byte[] bytes=text.toString().getBytes(StandardCharsets.UTF_8);require(bytes.length==parsed.sizeBytes()&&HexFormat.of().formatHex(CanonicalValueCodec.digest().digest(bytes)).equals(parsed.sha256()),FINGERPRINT_MISMATCH);
   var bounds=new DocumentBounds(file,revision.string("id"),document.string("id"),selection.parserVersion(),parsed.sha256(),sourceUnits,index.budget.canonical().maxContainerEntries());SourceVersion version;
   if(reference.string("kind").equals("LOCAL")){require(file.equals(reference.nullableString("file_id"))&&reference.nullableString("provider_id")==null&&reference.nullableString("external_id")==null&&revision.nullableString("external_version")==null,SOURCE_MEMBERSHIP_MISMATCH);version=new FileVersion(file,revision.string("id"),document.string("id"),selection.parserVersion(),parsed.sha256());}
   else{version=new KnowledgeVersion(revision.string("id"),reference.string("provider_id"),reference.string("external_id"),revision.string("external_version"),file,document.string("id"),selection.parserVersion(),parsed.sha256());out.add(new CatalogFact(new KnowledgeLocator(revision.string("id")),Role.BACKGROUND,version,content.sha256(),0,new KnowledgeBounds(revision.string("id"),reference.string("provider_id"),reference.string("external_id"),revision.string("external_version"),file,content.sha256())));}
   for(var unit:units){Locator locator;if(format.equals("PDF")||format.equals("PPT")){require(unit.string("kind").equals("PAGE")&&unit.nullableNumber("page_no")!=null&&unit.nullableNumber("paragraph_no")==null&&unit.nullableString("section_path")==null,LOCATOR_INVALID);locator=new PageLocator(format.equals("PDF")?PageKind.PDF_PAGE:PageKind.PPT_PAGE,file,unit.number("page_no"));}else{require(unit.string("kind").equals("PARAGRAPH")&&unit.nullableNumber("paragraph_no")!=null&&unit.nullableNumber("page_no")==null,LOCATOR_INVALID);locator=new ParagraphLocator(format.equals("WORD")?ParagraphKind.WORD_PARAGRAPH:ParagraphKind.TEXT_PARAGRAPH,file,unit.number("paragraph_no"),unit.nullableString("section_path"));}require(locators.add(locator),SOURCE_CONTEXT_AMBIGUOUS);out.add(new CatalogFact(locator,Role.BACKGROUND,version,content.sha256(),0,bounds));}
  }
  return List.copyOf(out);
 }
 static CanonicalValue manifest(StoredFactsIndex index,String snapshot,GenerationConfiguration config){if(snapshot==null)return object(field("mode",string("EMPTY")),field("items",list()));var selected=index.one(Table.MATERIAL_SNAPSHOT,snapshot,PROVENANCE_UNAVAILABLE);var members=new ArrayList<>(index.matching(Table.MATERIAL_SNAPSHOT_ITEM,"snapshot_id",snapshot));members.sort(Comparator.comparingLong(m->m.number("ordinal")));var items=new ArrayList<CanonicalValue>();long ordinal=0;for(var member:members){require(member.number("ordinal")==++ordinal,SOURCE_MEMBERSHIP_MISMATCH);String revision=member.string("material_revision_id");var row=index.one(Table.MATERIAL_REVISION,revision,PROVENANCE_UNAVAILABLE);var reference=index.one(Table.MATERIAL_REFERENCE,row.string("reference_id"),PROVENANCE_UNAVAILABLE);var selection=config.parserSelections().stream().filter(s->revision.equals(s.materialRevisionId())).findFirst().orElseThrow(()->fail(PROVENANCE_UNAVAILABLE));var document=index.single(index.matching(Table.PARSED_DOCUMENT,"material_revision_id",revision).stream().filter(d->selection.parserVersion().equals(d.string("parser_version"))).toList(),PROVENANCE_UNAVAILABLE);var profile=MaterialBinding.one(index.facts.rows(),Table.PARSED_DOCUMENT_PROFILE,"document_id",document.string("id"));var rows=new ArrayList<FullRow>(List.of(row,reference,document,profile));rows.addAll(index.matching(Table.PARSED_UNIT,"document_id",document.string("id")));items.add(object(field("ordinal",number(ordinal)),field("materialRevisionId",string(revision)),field("parsedDocumentId",string(document.string("id"))),field("contentHash",string(RowsetProjection.hash(rows,Set.of(Table.MATERIAL_REFERENCE,Table.MATERIAL_REVISION,Table.PARSED_DOCUMENT,Table.PARSED_DOCUMENT_PROFILE,Table.PARSED_UNIT),index)))));}return object(field("mode",string("PINNED")),field("snapshotId",string(snapshot)),field("revision",number(selected.number("revision"))),field("inputFingerprint",string(selected.string("input_fingerprint"))),field("contextId",string(config.inputId())),field("items",new Sequence(items)));}
 private MaterialCatalog(){}
}
